import os
import requests

files = {"logo": open("path/to/file", "rb")}
requests.put(
    "https://fornex.com/api/project/{id}/edit_logo/".format(
        id=1,
    ),
    headers={"Authorization": "Api-Key {}".format(os.getenv("FORNEX_API_KEY"))},
    files=files,
)

import os
import requests

requests.post(
    "https://fornex.com/api/tickets/ticket/",
    headers={"Authorization": "Api-Key {}".format(os.getenv("FORNEX_API_KEY"))},
    json={
        "subject": "Hello, we need some help",
        "message": "We need some help with updating software...",
    },
)

url.description:
The URL to which the POST request is sent.

Full list of details is sent (like in [Order Details](#tag/Orders/operation/orders_retrieve) method), but with extra field called `credentials`:
```json
{
  "credentials": {
    "ip_address": "127.0.0.1",
    "username": "root",
    "password": "root_pass"
  }
}
```

